import { drizzle } from "drizzle-orm/postgres-js";
import { migrate } from "drizzle-orm/postgres-js/migrator";
import postgres from "postgres";

/**
 * Run with: npm run db:migrate
 * Applies migrations generated by `npm run db:generate` (drizzle-kit) to the
 * database at DATABASE_URL. Safe to run repeatedly: drizzle records what has
 * already been applied in __drizzle_migrations.
 */
async function main() {
  const url = process.env.DATABASE_URL;
  if (!url) {
    console.error("DATABASE_URL is not set. Add it to .env.local first.");
    process.exit(1);
  }

  const sql = postgres(url, { max: 1 });

  // Print the target so you can confirm which database you are about to
  // change. Never prints the password.
  const { host, database } = sql.options;
  const hosts = Array.isArray(host) ? host.join(", ") : String(host);
  console.log(`Target: ${hosts}/${database}`);

  const db = drizzle(sql);
  await migrate(db, { migrationsFolder: "./drizzle" });
  await sql.end();
  console.log("Migrations applied.");
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
